"""POSIX-style word splitting with quoting and no expansions. See task.md."""

from __future__ import annotations


class SplitError(ValueError):
    """Raised for an unterminated quote or a lone trailing backslash."""


_SEPARATORS = " \t"
_DOUBLE_QUOTE_ESCAPABLE = "$`\"\\"


def split(line: str) -> list[str]:
    """Split `line` into words. See task.md for the rules."""
    words: list[str] = []
    buf: list[str] = []
    in_word = False
    i = 0
    n = len(line)
    while i < n:
        c = line[i]
        if c in _SEPARATORS:
            if in_word:
                words.append("".join(buf))
                buf = []
                in_word = False
            i += 1
        elif c == "'":
            end = line.find("'", i + 1)
            if end == -1:
                raise SplitError("unterminated single quote")
            buf.append(line[i + 1 : end])
            in_word = True
            i = end + 1
        elif c == '"':
            in_word = True
            i += 1
            while True:
                if i >= n:
                    raise SplitError("unterminated double quote")
                c = line[i]
                if c == '"':
                    i += 1
                    break
                if c == "\\" and i + 1 < n:
                    nxt = line[i + 1]
                    if nxt in _DOUBLE_QUOTE_ESCAPABLE:
                        buf.append(nxt)
                        i += 2
                        continue
                    if nxt == "\n":
                        i += 2
                        continue
                buf.append(c)
                i += 1
        elif c == "\\":
            if i + 1 >= n:
                raise SplitError("trailing backslash")
            nxt = line[i + 1]
            if nxt != "\n":
                buf.append(nxt)
                in_word = True
            i += 2
        elif c == "#" and not in_word:
            break
        else:
            buf.append(c)
            in_word = True
            i += 1
    if in_word:
        words.append("".join(buf))
    return words
